import{z as A,x as i,o as s,c as p,q as B,j as l,D as e,d as r,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"延迟长尾的追猎案例","description":"","frontmatter":{"title":"延迟长尾的追猎案例","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-tail-latency-case.md","filePath":"cs/pe3-tail-latency-case.md","lastUpdated":1791413859000}'),c={name:"cs/pe3-tail-latency-case.md"};function d(C,a,m,D,f,h){const t=i("Mermaid");return s(),p("div",null,[a[2]||(a[2]=B('<h1 id="延迟长尾的追猎案例" tabindex="-1">延迟长尾的追猎案例 <a class="header-anchor" href="#延迟长尾的追猎案例" aria-label="Permalink to &quot;延迟长尾的追猎案例&quot;">​</a></h1><div class="epigraph"><p>均值是报表的语言，分位是体验的语言；长尾追猎的第一步不是优化，是把报表从平均数上拆下来。</p><footer>—— 据 Dean 与 Barroso，The Tail at Scale，CACM 2013 口径整理</footer></div><p><a href="/cs/pe3-capacity-case">上一课</a>用容量曲线与安全水位把大促峰值接住了。但大促当晚的仪表盘上，p50 是 40 ms、p99 却是 2.4 s：容量够，尾炸了。本课追这条尾——它的猎法与均值不同源，用均值问题的思路打尾，枪枪落空。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均值由服务时间的中心决定，尾由<strong>变异</strong>与<strong>等待</strong>决定，两者的嫌疑人名单不同。常见嫌疑：GC 停顿与周期性后台任务（慢簇固定出现在整点或固定间隔）、缓存失效惊群（过期瞬间一群请求同砸下游）、共享资源上的排队（日志刷盘、<a href="/cs/fsync">fsync</a>、锁）、以及慢邻居与坏实例。不这么做会错在哪：只看聚合监控——几百个实例的分位混平均，尾被抹成一条平线；或者优化均值路径，把序列化再加快一倍，而 200 ms 的坑根本是每分钟一次的 GC。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，先把尾切开，再谈优化。按三个维度切分位数：<strong>时间</strong>（慢是否聚在固定时刻）、<strong>特征</strong>（慢是否聚在特定请求——大请求、缓存未命中、特定分片）、<strong>实例</strong>（慢是否聚在固定节点）。聚合看不见的簇，切开后自己显形。<a href="/cs/obs-distributed-tracing">分布式追踪</a>把端到端的尾拆到跳，定位它住在哪一跳。</p><p><span class="marginnote">「三维切分」可以想象成查堵车：不问「全城平均车速多少」（那是均值，永远 40 迈），而是问——堵车是不是都发生在早八点（时间）？是不是都堵在货车走的路线（特征）？是不是总卡在某一座桥（实例）？三个问题分别对应慢在何时、何种请求、哪台机器，交叉一下嫌疑范围就缩到很小。</span></p><p>第二步，on-CPU 之外查 off-CPU。等锁、等 IO、等调度不在 CPU 剖面里，要用<a href="/cs/obs-perf-deep">perf 的深化</a>的调度事件把等待时间聚成直方图；GC 停顿要看运行时的停顿日志而不是猜。本案例的 2.4 s 最后对上两个来源：缓存批量过期造成的下游惊群，叠加过载时段入口队列的排队。</p><p>第三步，机制层砍尾。缓存过期改逻辑过期加互斥重建（<a href="/cs/cache-stampede-hotkey">缓存雪崩与热键</a>）；入口队列上主动队列管理，早丢早拒绝而不是让请求排到超时（<a href="/cs/aqm-red-codel">AQM：RED 与 CoDel</a>）；读路径加对冲请求，扇出链路用<a href="/cs/tail-latency-hedging">尾延迟与对冲请求</a>与<a href="/cs/tail-at-scale">Tail at Scale</a>的分层对策。</p><p>第四步，收账回到 SLO。修复后分位写回错误预算（<a href="/cs/obs-slo-engineering">SLO 工程</a>），并与容量课的安全水位对表：砍尾如果吃掉了吞吐，水位要重新画。</p>',11)),(s(),l(n,null,{default:e(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALARM%5B%22%E5%88%86%E4%BD%8D%E6%8A%A5%E8%AD%A6%EF%BC%9Ap99%20%3D%202.4%20s%22%5D%20--%3E%20CUT%5B%22%E4%B8%89%E7%BB%B4%E5%88%87%E5%88%86%EF%BC%9A%E6%97%B6%E9%97%B4%E3%80%81%E7%89%B9%E5%BE%81%E3%80%81%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20CUT%20--%3E%20TRACE%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E8%BF%BD%E8%B8%AA%E6%8B%86%E5%88%B0%E8%B7%B3%22%5D%0A%20%20TRACE%20--%3E%20OFFCPU%5B%22off-CPU%20%E4%B8%8E%E5%81%9C%E9%A1%BF%E6%97%A5%E5%BF%97%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20OFFCPU%20--%3E%20SRC%5B%22%E5%AE%9A%E4%BD%8D%EF%BC%9A%E7%BC%93%E5%AD%98%E6%83%8A%E7%BE%A4%E5%8F%A0%E5%8A%A0%E6%8E%92%E9%98%9F%22%5D%0A%20%20SRC%20--%3E%20FIX%5B%22%E6%9C%BA%E5%88%B6%E5%B1%82%E5%AF%B9%E7%AD%96%EF%BC%9A%E4%BA%92%E6%96%A5%E9%87%8D%E5%BB%BA%E3%80%81AQM%E3%80%81%E5%AF%B9%E5%86%B2%22%5D%0A%20%20FIX%20--%3E%20VERI%7B%22%E5%88%86%E4%BD%8D%E5%9B%9E%E9%A2%84%E7%AE%97%EF%BC%8C%E6%B0%B4%E4%BD%8D%E4%B8%8D%E5%8F%98%22%7D%0A%20%20VERI%20--%3E%7C%22%E5%90%9E%E5%90%90%E8%A2%AB%E5%90%83%22%7C%20CAP%5B%22%E5%9B%9E%E5%AE%B9%E9%87%8F%E8%AF%BE%E9%87%8D%E7%94%BB%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20VERI%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20DONE%5B%22%E7%BB%93%E6%A1%88%EF%BC%9A%E5%86%99%E5%85%A5%E5%88%A4%E6%8D%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"扇出为什么放大尾：一次请求等 \\(N\\) 个依赖，用户等待是各依赖延迟的 max——一百个依赖各自只有 1% 的概率超过 10 ms，整体至少一个超标的概率是 \\(1-0.99^{100}\\approx 63\\%\\)。稀有慢在扇出后变成常态慢，这是 Dean–Barroso 的原始论点，也是对冲请求存在的理由。变异为什么进排队账：Pollaczek–Khinchine 公式 \\(W_q\\approx\\dfrac{\\rho}{1-\\rho}\\cdot\\dfrac{1+C_s^{2}}{2\\mu}\\) 里，等待随服务时间变异系数 \\(C_s\\) 线性涨——均值相同、变异翻倍的服务，在高利用率下排队等待同样翻倍；这就是「削平变异」（隔离、互斥重建、早拒绝）与「加机器」不等价、且常常更便宜的原因。对冲为什么要有预算：过载时所有请求都慢，对冲退化为同步双发，负载放大趋近两倍并正反馈——所以触发条件要延迟化，且能自动关闭。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"本案例的 2.4 s 不是任何一跳的正常耗时：惊群那一跳 p99 是 300 ms，入口排队再乘一个过载因子。长尾案件里最常见的结论是「两个各不致命的来源在同一个瞬间相遇」——单变量排查在这里会漏案，要在同一时间轴上对齐多路证据。")],-1)),(s(),l(n,null,{default:e(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20REQ%5B%22%E4%B8%80%E6%AC%A1%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20F1%5B%22%E4%BE%9D%E8%B5%96%201%EF%BC%9Ap99%20%3D%2010%20ms%22%5D%0A%20%20REQ%20--%3E%20F2%5B%22%E4%BE%9D%E8%B5%96%202%EF%BC%9Ap99%20%3D%2010%20ms%22%5D%0A%20%20REQ%20--%3E%20F3%5B%22%E4%BE%9D%E8%B5%96%20100%EF%BC%9Ap99%20%3D%2010%20ms%22%5D%0A%20%20F1%20%26%20F2%20%26%20F3%20--%3E%20MAX%5B%22%E7%94%A8%E6%88%B7%E7%AD%89%E6%9C%80%E6%85%A2%E7%9A%84%E9%82%A3%E4%B8%AA%EF%BC%9Amax%22%5D%0A%20%20MAX%20--%3E%20OUT%5B%22%E8%87%B3%E5%B0%91%E4%B8%80%E4%B8%AA%E6%92%9E%E6%85%A2%E7%9A%84%E6%A6%82%E7%8E%87%20%E2%89%88%2063%25%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>这张图回答的问题是：每个依赖都很快，为什么用户还是慢？扇出请求要等所有依赖返回，用户等待取的是 max 而不是平均。一百个依赖各自只有 1% 的概率超过 10 ms，几乎可以肯定其中有一个这次就是慢的——单点的「稀有慢」经过扇出被放大成用户的「经常慢」。对冲请求（同发多份、谁先回用谁）就是买断这种 max 风险的保险。</p><p><span class="marginnote">数字实例（变异进排队账）：两个服务均值都是 10 ms，一个变异系数 \\(C_s=1\\)（波动与均值相当），另一个 \\(C_s=3\\)（忽快忽慢）。排队公式里等待正比于 \\(1+C_s^2\\)：前者系数是 1，后者是 5——利用率 80% 时，前者排队约 8 ms，后者要等 40 ms。均值一点没变，体验翻了五倍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有分位都值得砍：第一课的 SLO 只承诺到 p99，p99.9 的尾可能属于另一本预算，为它付架构税要先立项。砍尾的手段各有代价——隔离降低利用率（与容量课的水位直接冲突）、对冲加负载、早拒绝牺牲吞吐——都要与错误预算对账后选型。跨地域的尾有光速下限，不是工程能砍掉的。本课不重讲<a href="/cs/tail-latency-hedging">尾延迟与对冲请求</a>的触发参数学与<a href="/cs/tail-at-scale">Tail at Scale</a>的微分区机制，只给把它们放进案件的顺序：先切分、再归因、后选机制。</p><p><span class="marginnote">常见误区：以为「尾慢就是机器不够多」。如果是 GC 停顿或缓存惊群造成的慢簇，加机器只是把同一个整点停顿摊到更多实例上，p99 该跳还跳——而且实例一多，扇出放大反而更凶。先归因到机制（变异与等待），再决定是削变异还是加容量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>均值与尾不同源：尾由变异与等待决定，嫌疑人名单要先换再查。</li><li>三维切分（时间、特征、实例）让不可见的慢簇显形，聚合监控是帮凶。</li><li>off-CPU 与停顿日志是尾案件的常规证物；on-CPU 剖面查不出等待。</li><li>削平变异与加机器不等价：\\(C_s\\) 直接进排队公式，高利用率下更贵。</li><li>对冲与隔离都有账：负载放大与利用率损失要写进错误预算的对账单。</li><li>出处：Dean 与 Barroso，<em>The Tail at Scale</em>，CACM 2013；Gregg，<em>Systems Performance</em>，2nd ed., 2018；据本课四步追猎口径整理。</li></ul>',7))])}const g=A(c,[["render",d]]);export{_ as __pageData,g as default};
